// --- Rute POST /api/downloads ---
app.post('/api/downloads', upload.single('document_file'), async (req, res) => {
  try {
    const { document_title, access_level } = req.body;
    if (!document_title || !req.file) return res.status(400).json({ status: 'error', message: 'Judul dan File wajib diisi/diunggah.' });

    const file_path = '/uploads/' + req.file.filename;

    await db.execute(
      'INSERT INTO download_center (document_title, access_level, file_path) VALUES (?, ?, ?)',
      [document_title, access_level, file_path]
    );
    res.status(201).json({ status: 'success', message: 'Dokumen berhasil diunggah' });
  } catch (error) {
    console.error('Error posting download:', error);
    res.status(500).json({ status: 'error', message: 'Gagal mengunggah dokumen.' });
  }
});

// --- Rute PUT /api/admin/events/attendance ---
// Mengubah status kehadiran pendaftaran acara oleh admin
app.put('/api/admin/events/attendance', async (req, res) => {
  try {
    const { registration_id, status } = req.body;

    if (!registration_id || !status) {
      return res.status(400).json({ status: 'error', message: 'registration_id dan status wajib diisi.' });
    }

    const validStatuses = ['Registered', 'Attended', 'Absent'];
    if (!validStatuses.includes(status)) {
      return res.status(400).json({ status: 'error', message: `Status tidak valid. Gunakan salah satu dari: ${validStatuses.join(', ')}` });
    }

    const [result] = await db.execute(
      'UPDATE event_registrations SET attendance_status = ? WHERE registration_id = ?',
      [status, registration_id]
    );

    if (result.affectedRows === 0) {
      return res.status(404).json({ status: 'error', message: 'Data pendaftaran acara tidak ditemukan.' });
    }

    res.status(200).json({
      status: 'success',
      message: 'Status kehadiran berhasil diperbarui.',
      data: { registration_id, attendance_status: status }
    });
  } catch (error) {
    console.error('Error updating attendance:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memperbarui status kehadiran.' });
  }
});

// --- Rute GET /api/members/cpd/summary ---
// Mengambil ringkasan poin CPD anggota pada tahun berjalan (mock user_id = 1)
app.get('/api/members/cpd/summary', async (req, res) => {
  try {
    const userId = req.query.user_id || 1;
    const currentYear = new Date().getFullYear();

    const [rows] = await db.execute(
      `SELECT COALESCE(SUM(e.cpd_points), 0) AS total_points
       FROM event_registrations er
       JOIN events e ON er.event_id = e.event_id
       WHERE er.user_id = ?
         AND er.attendance_status = 'Attended'
         AND YEAR(e.event_date) = ?`,
      [userId, currentYear]
    );

    const totalPoints = Number(rows[0]?.total_points || 0);
    const targetPoints = 30;

    res.status(200).json({
      status: 'success',
      data: {
        user_id: Number(userId),
        year: currentYear,
        total_points: totalPoints,
        target_points: targetPoints
      }
    });
  } catch (error) {
    console.error('Error fetching CPD summary:', error);
    res.status(500).json({ status: 'error', message: 'Gagal mengambil data poin CPD.' });
  }
});

