// --- Fungsi Memuat Ringkasan Poin CPD ---
async function loadCpdSummary() {
    try {
        const response = await fetch('/api/members/cpd/summary?user_id=1');
        const result = await response.json();

        if (result.status === 'success' && result.data) {
            const totalPoints = result.data.total_points || 0;
            const targetPoints = result.data.target_points || 30;

            const progressBar = document.getElementById('cpd-progress-bar');
            const cpdText = document.getElementById('cpd-text');

            if (progressBar) {
                progressBar.value = totalPoints;
                progressBar.max = targetPoints;
            }

            if (cpdText) {
                cpdText.textContent = `Anda telah mengumpulkan ${totalPoints} / ${targetPoints} Poin CPD tahun ini.`;
            }
        }
    } catch (error) {
        console.error('Gagal mengambil data poin CPD:', error);
        const cpdText = document.getElementById('cpd-text');
        if (cpdText) {
            cpdText.textContent = 'Gagal memuat data poin CPD.';
        }
    }
}

// Jalankan loadCpdSummary saat halaman dimuat
document.addEventListener('DOMContentLoaded', loadCpdSummary);
```

